<template><section class="page-card"><div class="page-header"><div><h1 class="page-title">用户管理</h1><p class="muted">管理本地用户、启停状态及其角色。服务端会再次校验每项权限。</p></div><el-button v-has-permi="'system:user:create'" type="primary" @click="openCreate">新增用户</el-button></div><ManagementToolbar @search="load" @reset="reset"><el-input v-model="filters.keyword" placeholder="用户名或显示名称" clearable /><el-select v-model="filters.status" placeholder="账号状态" clearable><el-option label="启用" value="active" /><el-option label="停用" value="inactive" /></el-select></ManagementToolbar><div v-if="loading" class="loading-state"><el-icon class="is-loading"><Loading /></el-icon></div><el-table v-else :data="rows" border><el-table-column prop="username" label="用户名" min-width="130" /><el-table-column prop="displayName" label="显示名称" min-width="130" /><el-table-column label="角色" min-width="170"><template #default="{row}">{{ row.roles?.map(item=>item.roleName).join('、') || '-' }}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><StatusTag :status="row.status" /></template></el-table-column><el-table-column label="最后登录" min-width="160"><template #default="{row}">{{ formatDate(row.lastLoginAt) }}</template></el-table-column><el-table-column label="操作" min-width="270" fixed="right"><template #default="{row}"><div class="table-actions"><el-button v-has-permi="'system:user:update'" text type="primary" @click="openEdit(row)">编辑</el-button><el-button v-has-permi="'system:user:status'" text @click="toggleStatus(row)">{{row.status==='active'?'停用':'启用'}}</el-button><el-button v-has-permi="'system:user:assign-role'" text @click="openRoles(row)">分配角色</el-button><el-button v-has-permi="'system:user:reset-password'" text type="warning" @click="resetPassword(row)">重置密码</el-button><el-button v-has-permi="'system:user:delete'" text type="danger" :disabled="row.isBuiltin" @click="remove(row)">删除</el-button></div></template></el-table-column></el-table><el-pagination v-model:current-page="filters.page" v-model:page-size="filters.pageSize" class="pagination" layout="total, sizes, prev, pager, next" :total="total" @current-change="load" @size-change="load" /><ManagementDrawer v-model="drawer.open" :title="drawer.title" :loading="saving" @save="save"><el-form class="drawer-form" label-position="top"><el-form-item label="用户名" required><el-input v-model="form.username" :disabled="drawer.mode==='edit'" /></el-form-item><el-form-item v-if="drawer.mode==='create'" label="初始密码" required><el-input v-model="form.password" type="password" show-password /></el-form-item><el-form-item label="显示名称" required><el-input v-model="form.displayName" /></el-form-item><el-form-item label="角色" required><el-select v-model="form.roleIds" multiple style="width:100%"><el-option v-for="role in roles" :key="role.id" :label="role.roleName" :value="role.id" /></el-select></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="active">启用</el-radio><el-radio value="inactive">停用</el-radio></el-radio-group></el-form-item></el-form></ManagementDrawer></section></template>
<script setup>import { onMounted,reactive,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { request,query } from '@/api/http';import ManagementToolbar from '@/components/ManagementToolbar.vue';import ManagementDrawer from '@/components/ManagementDrawer.vue';import StatusTag from '@/components/StatusTag.vue';import { formatStrictUtcDateTimeDisplay } from '@/utils/dateTimeDisplay';const rows=ref([]),roles=ref([]),total=ref(0),loading=ref(false),saving=ref(false);const filters=reactive({keyword:'',status:'',page:1,pageSize:20});const drawer=reactive({open:false,title:'',mode:'create',id:null});const form=reactive({username:'',password:'',displayName:'',roleIds:[],status:'active'});const formatDate=value=>formatStrictUtcDateTimeDisplay(value,'-');async function load(){loading.value=true;try{const r=await request({url:'/system/users',params:query(filters)});rows.value=r.data||[];total.value=r.meta?.pagination?.total||0;}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}async function loadRoles(){const r=await request({url:'/system/roles'});roles.value=r.data||[]}function reset(){Object.assign(filters,{keyword:'',status:'',page:1});load()}function resetForm(){Object.assign(form,{username:'',password:'',displayName:'',roleIds:[],status:'active'})}function openCreate(){resetForm();Object.assign(drawer,{open:true,title:'新增用户',mode:'create',id:null})}function openEdit(row){resetForm();Object.assign(form,{displayName:row.displayName,roleIds:row.roles?.map(item=>item.id)||[],status:row.status});Object.assign(drawer,{open:true,title:'编辑用户',mode:'edit',id:row.id})}function openRoles(row){openEdit(row);drawer.title='分配角色'}async function save(){if(!form.displayName||!form.roleIds.length||(drawer.mode==='create'&&(!form.username||form.password.length<8)))return ElMessage.warning('请完整填写必填字段，初始密码至少 8 位。');saving.value=true;try{if(drawer.mode==='create')await request({method:'post',url:'/system/users',data:form});else{await request({method:'put',url:`/system/users/${drawer.id}`,data:{displayName:form.displayName,status:form.status}});await request({method:'put',url:`/system/users/${drawer.id}/roles`,data:{roleIds:form.roleIds}})}ElMessage.success('保存成功。');drawer.open=false;load()}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}async function toggleStatus(row){try{await ElMessageBox.confirm(`确定${row.status==='active'?'停用':'启用'}用户“${row.username}”吗？`,'状态确认',{type:'warning'});await request({method:'patch',url:`/system/users/${row.id}/status`,data:{status:row.status==='active'?'inactive':'active'}});ElMessage.success('状态已更新。');load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}async function resetPassword(row){try{const {value}=await ElMessageBox.prompt(`为“${row.username}”设置至少 8 位的新密码。`,'管理员重置密码',{inputType:'password',inputPattern:/.{8,}/,inputErrorMessage:'新密码至少 8 位。'});await request({method:'put',url:`/system/users/${row.id}/reset-password`,data:{newPassword:value}});ElMessage.success('密码已重置，目标用户既有会话已失效。')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}async function remove(row){try{await ElMessageBox.confirm(`删除“${row.username}”仅适用于无关联账号；通常建议停用。是否继续？`,'删除用户',{type:'warning'});await request({method:'delete',url:`/system/users/${row.id}`});ElMessage.success('用户已删除。');load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}onMounted(async()=>{await Promise.all([load(),loadRoles()])});</script>
<style scoped>.pagination{justify-content:flex-end;margin-top:16px}</style>
